      const int64_t f1f2_2 = f1_2 * static_cast<int64_t>(f2);
      const int64_t f1f3_4 = f1_2 * static_cast<int64_t>(f3_2);
      const int64_t f1f4_2 = f1_2 * static_cast<int64_t>(f4);
      const int64_t f1f5_4 = f1_2 * static_cast<int64_t>(f5_2);
