   const int64_t f3f3_2 = f3_2 * static_cast<int64_t>(f3);
   const int64_t f3f4_2 = f3_2 * static_cast<int64_t>(f4);
   const int64_t f3f5_4 = f3_2 * static_cast<int64_t>(f5_2);
